pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testRegression_property() public {
        address alice = address(0x1234);
        uint256 max = type(uint256).max;
        vm.deal(alice, max);
        vm.prank(alice);
        c.addToBalance{value: max}();
        vm.prank(alice);
        bool ok;
        try c.addToBalance{value: 1}() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok == false);
    }
}
